package com.dbshield; import java.sql.*; import java.io.*; public class DumpDb { public static void main(String[] args) throws Exception { try (Connection conn = DriverManager.getConnection("jdbc:h2:file:./dbshield;MODE=PostgreSQL;DATABASE_TO_LOWER=TRUE", "sa", "password"); PrintWriter pw = new PrintWriter("src/main/resources/db/migration/V3__import_backup.sql")) { ResultSet rs = conn.createStatement().executeQuery("SELECT * FROM users"); while(rs.next()) { pw.printf("INSERT INTO users (username, password, full_name, country, city, phone, role, is_active) VALUES ('%s', '%s', '%s', '%s', '%s', '%s', 'ADMIN_DBA', %b) ON CONFLICT (username) DO UPDATE SET password = EXCLUDED.password, role = 'ADMIN_DBA';\n", rs.getString("username"), rs.getString("password"), rs.getString("full_name"), rs.getString("country"), rs.getString("city"), rs.getString("phone"), rs.getBoolean("is_active")); } System.out.println("V3_CREATED"); } } }
